// ===== ARE YOU THE GOAT? — DATA POOLS =====
// Ratings are fictional flavor values for gameplay, not real stat claims.
// Rosters are a v1 approximation for flavor, not an exhaustive database.

// Each roster row:
// [name, era, heightLabel, heightRating, athleticismLabel, athleticismRating,
//  Shooting, Finishing, Playmaking, Handles, Defense, Rebounding]
function hydrateRosterRow([name, era, hLabel, hRating, aLabel, aRating, sh, fi, pl, ha, de, re]) {
  return {
    name, era,
    height: { label: hLabel, rating: hRating },
    athleticism: { label: aLabel, rating: aRating },
    skills: { Shooting: sh, Finishing: fi, Playmaking: pl, Handles: ha, Defense: de, Rebounding: re },
  };
}

