const COMP_PLAYERS = COMP_ROWS.map(([name, pos, height, athleticism, sh, fi, pl, ha, de, re, rings, mvps, finalsMVPs, allNBA, allStar, reasoning]) => ({
  name, pos,
  dims: { height, athleticism, Shooting: sh, Finishing: fi, Playmaking: pl, Handles: ha, Defense: de, Rebounding: re },
  accomplishments: { rings, mvps, finalsMVPs, allNBA, allStar },
  reasoning,
}));

if (typeof module !== "undefined") {
  module.exports = { TEAM_ROSTERS, BUDGET_BIN, TEAMS, TEAM_FIVES, POSITIONS, COMP_PLAYERS, SHADOW_TARGETS, SHADOW_ORDER, TRAIT_BADGES };
}
